// n8n Code node
// Devuelve el mismo input, pero si encuentra uno de los modelos en `productoInteres`,
// lo normaliza y deja SOLO esa palabra/frase (de la lista). Si no encuentra, no toca nada.

const MODELOS = [
  "Frontier",
  "X-Trail e-Power",
  "X-Trail",
  "Nuevo Kicks",
  "Kicks Play",
  "Sentra",
  "Versa",
  "KAIT"
];

const ALIASES = {
  "kicks sense": "Kicks Play",
  "kicks advance": "Kicks Play",
  // agregá más variantes acá si aparecen
};

// Normalización simple (case-insensitive, ignora dobles espacios y guiones raros)
function norm(s) {
  return String(s || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ")
    .replace(/[‐-–—]/g, "-");
}

const modelosNorm = MODELOS.map((m) => ({ raw: m, n: norm(m) }));

return items.map((item) => {
  const pi = item.json?.productoInteres;
  if (!pi) return item; // no hay productoInteres → devolver tal cual

  const piNorm = norm(pi);

  // Primero revisar aliases exactos
  if (ALIASES[piNorm]) {
    return {
      ...item,
      json: {
        ...item.json,
        productoInteres: ALIASES[piNorm],
      },
    };
  }

  // Después el match normal por "contiene"
  // prioriza el match más largo (ej: "X-Trail e-Power" antes que "X-Trail")
  const match = modelosNorm
    .filter((m) => piNorm.includes(m.n))
    .sort((a, b) => b.n.length - a.n.length)[0];

  if (!match) return item; // no encontró → devolver tal cual

  return {
    ...item,
    json: {
      ...item.json,
      productoInteres: match.raw, // deja solo el modelo encontrado
    },
  };
});

